### Batch extraction script with JSONL + CSV outputs
This variant writes reusable structured outputs that can feed directly into document-organizer workflows.

```python
#!/usr/bin/env python3
import csv, json, re, subprocess
from pathlib import Path

TOPIC_RULES = {
    "LLM": ["llm", "transformer", "language model", "prompt"],
    "trapped_ion_and_qc": ["trapped ion", "quantum", "qubit"],
    "black_hole": ["black hole", "hawking", "event horizon"],
    "DNA": ["dna", "genome", "sequencing"],
    "music_history": ["music", "composer", "baroque", "classical"]
}


def classify(text: str) -> str:
    t = text.lower()
    scores = {
        k: sum(1 for kw in kws if kw in t)
        for k, kws in TOPIC_RULES.items()
    }
    return max(scores, key=scores.get)


def extract(docx_path: Path):
    md = subprocess.check_output([
        "pandoc", "--track-changes=accept", "-t", "gfm", str(docx_path)
    ]).decode("utf-8", errors="replace")

    lines = [l.strip() for l in md.splitlines()]
    headings = [
        re.sub(r"^#+\\s+", "", l)
        for l in lines if re.match(r"^#+\\s+", l)
    ]
    title = headings[0] if headings else docx_path.stem
    body = [l for l in lines if l and not l.startswith("#")]
    lead = re.sub(r"\\s+", " ", " ".join(body))[:800]
    return {
        "file": docx_path.name,
        "type": "docx",
        "title": title,
        "headings": headings[:10],
        "lead": lead
    }


rows = []
for p in sorted(Path('.').glob('*.docx')):
    rec = extract(p)
    rec["category"] = classify(
        " ".join([rec["title"], rec["lead"], " ".join(rec["headings"])])
    )
    rows.append(rec)

with open("features.jsonl", "w", encoding="utf-8") as f:
    for r in rows:
        f.write(json.dumps(r, ensure_ascii=False) + "\\n")

with open("routing.csv", "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    w.writerow(["file", "category", "destination"])
    for r in rows:
        w.writerow([
            r["file"],
            r["category"],
            f'{r["category"]}/{r["file"]}'
        ])
```

